22: // building a trace that can never advance.
23: export function createTraceMachine({
24:   stage,
25:   serverAddress,
26:   servers,
27:   lb = null,
28:   network,
29:   cache = null,
30:   database = null,
31:   workerQueue = null,
32:   dns = null,
33:   cdn = null,
34:   router = null,
35:   bumpTick,
36:   getTick,
37:   onServe,
38:   onFinish,
39:   onDnsFail = null,
40:   onRefusal = null,
41: }) {
42:   if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
43:     throw new Error(`trace: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
44:   }
45:   if (stage === 6) {
46:     return createStage6Trace({
47:       serverAddress,
48:       servers,
49:       lb,
50:       network,
51:       dns,
52:       cdn,
53:       router,
54:       cache,
55:       database,
56:       workerQueue,
57:       bumpTick,
58:       getTick,
59:       onServe,
60:       onFinish,
61:       onDnsFail,
62:     });
63:   }
64:   const RESET_FIELDS = {
65:     cacheStatus: null,
66:     dbOp: null,
67:     dbStale: false,
68:     response: null,
69:     status: null,
70:     body: null,
71:     routeId: null,
72:     refused: false,
73:   };
