78:   function freshTrace() {
79:     return {
80:       hop: 0,
81:       method: 'GET',
82:       path: '/about',
83:       from: '10.2',
84:       request: 'GET /about',
85:       targetServer: null,
86:       ...RESET_FIELDS,
87:     };
