179:       // Final hop count comes from the live trace shape: 2 once the answer
180:       // says NX, 6 for a CDN GET served from the edge ledger (HIT), 9 for a
181:       // CDN MISS or non-GET pass-through, 9 for other hosted paths, 8
182:       // host-less.
183:       const finalHop = trace.nx
184:         ? 2
185:         : trace.cdn
186:           ? trace.edgeStatus === 'HIT'
187:             ? 6
188:             : 9
189:           : trace.host
190:             ? 9
191:             : 8;
192:       let frame;
193:       if (trace.hop === 0 || trace.hop >= finalHop) {
