200:         // old "10.2 -> example.com | GET ..." narrated a delivery the
201:         // component model never makes — DL-4; for an NX host no GET exists
202:         // at all). Host-less emission keeps the stage-5 emit frame verbatim.
203:         const slash = String(path).indexOf('/');
204:         const host =
205:           slash === -1 ? String(path) : slash === 0 ? null : String(path).slice(0, slash);
206:         const rest = slash === -1 ? '/' : String(path).slice(slash);
207:         const request = `${method} ${path}`;
208:         trace = { ...freshTrace(), hop: 1, method, path: rest, host: host || null, request, from };
209:         served = null;
210:         answer = null;
211:         if (host) {
212:           // Hop 1 of the hosted shape is the ask: the DNS ledger lookup
213:           // runs right here, feeding the answer hop the component's real
214:           // result.
215:           answer = dns.lookup(host, getTick());
216:           frame = `${from} -> ${dns.address} | who is ${host}?`;
217:         } else {
218:           frame = `${from} -> ${serverAddress} | ${request}`;
