```js
// The shared LB hop: one implementation of the B-6b branch, moved
// byte-shape-identical from trace.js's stage-5 branch so both machines
// (trace.js and trace-stage6.js's chainStep(2)) tell one LB story.
// DOCUMENTS: ...
// CHECKS: named counter-examples — an all-down pool returns the refusal
// record and the frame is the refusal card (no [object Object], nothing
// enqueued); a one-down pool's selection narrates the crossed seat via the
// LB's lastSkip(); a healthy pick keeps the clean byte shape.
export function lbEnqueueHop(trace, { serverAddress, lb, bumpTick, onRefusal }) {
  const atTick = bumpTick();
  const target = lb.enqueue({
    id: `you:${atTick}`,
    from: trace.from,
    to: serverAddress,
    request: trace.request,
    atTick,
    isYou: true,
  });
  if (target?.refused === true) {
    trace.refused = true;
    onRefusal?.(target);
    return { frame: lbRefusedFrame(serverAddress, target, trace.request), refused: true };
  }
  trace.targetServer = target;
  return {
    frame: lbEnqueuedFrame(serverAddress, target, trace.request, lb.lastSkip?.()),
    refused: false,
  };
}
```

