export function lbRefusedFrame(serverAddress, record, request) {
  return `LB ${serverAddress} -> ${record.to} | ${request} => connection refused (nothing enqueued)`;
}

// The shared LB hop (R1a, docs/plans/2026-11-01-r1a-stage6-lb-hop-unification.md):
// the B-6b branch text moved byte-shape-identical out of trace.js's stage-5
// branch so BOTH machines tell one LB story — trace.js's stage-2..5 machine
// and trace-stage6.js's chainStep(2). Pure over its inputs plus the live
// trace object (same seam discipline as the other helpers: trace mutates in
// place, no engine closures).
//
// CHECKS: the named counter-examples — an all-down pool hands back the
// refusal record, so the trace aborts at this hop with the refusal card
// (no [object Object] in the frame, nothing enqueued, no phantom chain);
// a one-down pool's selection narrates the crossed seat via the LB's own
// lastSkip(); a healthy pick keeps the clean byte shape. On refusal the
// trace is marked refused and onRefusal fires (the engine renders the
// connection-refused card); on enqueue the trace takes the selected
// backend. Returns { frame, refused }.
export function lbEnqueueHop(trace, { serverAddress, lb, bumpTick, onRefusal }) {
  const atTick = bumpTick();
  const target = lb.enqueue({
    id: `you:${atTick}`,
    from: trace.from,
    to: serverAddress,
    request: trace.request,
    atTick,
    isYou: true,
  });
  if (target?.refused === true) {
    trace.refused = true;
    onRefusal?.(target);
    return { frame: lbRefusedFrame(serverAddress, target, trace.request), refused: true };
  }
  trace.targetServer = target;
  return {
    frame: lbEnqueuedFrame(serverAddress, target, trace.request, lb.lastSkip?.()),
    refused: false,
  };
}

